// Point and BBox interfaces are now imported from constants

export interface Group extends BBox {
	id: string;
	name: string;
	nodes: (Node | Group)[];
	ref?: SVGGElement;
	style: NodeStyle;
	layoutBounds?: BBox;
	layoutTitleBounds?: BBox;
}

export interface NodeLink {
	href: string;
	exportHref: string;
}

export type LayoutDirection = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export interface Node extends BBox {
	id: string;
	title: string;
	sub: string;
	description: string;

	ref?: SVGGElement;
	selected?: boolean;

	intersect: (p: Point) => Point

	style: NodeStyle
	link?: NodeLink
	contentLayout: NodeContentLayout
}

// NodeStyle interface is now imported from constants

